import { test, expect } from "@playwright/test";
import { readFileSync } from "node:fs";
import { join } from "node:path";

/**
 * Arc A ("results depth") e2e coverage: the Stats tab, pin-as-headline, and
 * the reaction-override dropdown (Tasks 1, 2, 6). Engine-side expectations
 * live in e2e/fixtures/results-depth.json, regenerated by
 * lib/__tests__/sweepExpectations.gen.test.ts on every unit-test run
 * (Playwright's runner cannot import the ESM-only @genshin/data directly —
 * same rationale as sweep-selfbuffs.spec.ts).
 */

interface StatsCase {
  hash: string;
  statKey: string;
  expectedTotal: number;
}

interface PinCase {
  hash: string;
  pinKey: string;
  pinnedHeadline: number;
}

interface VaporizeCase {
  hash: string;
  featureLabel: string;
  featureKey: string;
  expectedAmped: number;
  expectedBase: number;
}

interface Fixture {
  stats: StatsCase;
  pin: PinCase;
  vaporize: VaporizeCase;
  quicken: VaporizeCase;
}

const fixture: Fixture = JSON.parse(
  readFileSync(join(__dirname, "fixtures", "results-depth.json"), "utf8")
);

// Same formatter the app uses for every rendered stat/damage number
// (lib/motion.ts's `fmt`, lib/statSheet.ts's `fmtFlat`, Breakdown.tsx's `fmt`).
const fmt = (n: number) => Math.round(n).toLocaleString("en-US");

test("Stats tab shows the engine's ATK total", async ({ page }) => {
  await page.goto(`/#${fixture.stats.hash}`);
  await expect(page.getByTestId("result-avg").first()).toBeVisible({ timeout: 10_000 });

  await page.getByTestId("results-tab-stats").click();
  await expect(page.getByTestId(`stat-total-${fixture.stats.statKey}`)).toHaveText(
    fmt(fixture.stats.expectedTotal)
  );
});

test("pinning a non-highest feature swaps the Stage headline", async ({ page }) => {
  await page.goto(`/#${fixture.pin.hash}`);
  await expect(page.getByTestId("result-avg").first()).toBeVisible({ timeout: 10_000 });

  await page.getByTestId(`pin-${fixture.pin.pinKey}`).click();
  await expect(page.getByTestId("headline-avg")).toHaveText(fmt(fixture.pin.pinnedHeadline), {
    timeout: 5_000,
  });
});

test("reaction override amplifies the feature, and reverting to None restores the base value", async ({
  page,
}) => {
  await page.goto(`/#${fixture.vaporize.hash}`);
  await expect(page.getByTestId("result-avg").first()).toBeVisible({ timeout: 10_000 });

  await expect(page.getByText(fmt(fixture.vaporize.expectedAmped), { exact: true }).first()).toBeVisible({
    timeout: 5_000,
  });

  await page.getByTestId("reaction-select").selectOption("");
  await expect(page.getByText(fmt(fixture.vaporize.expectedBase), { exact: true }).first()).toBeVisible({
    timeout: 5_000,
  });
});

test("quicken override raises the electro burst, and reverting to None restores the base value", async ({
  page,
}) => {
  await page.goto(`/#${fixture.quicken.hash}`);
  await expect(page.getByTestId("result-avg").first()).toBeVisible({ timeout: 10_000 });

  await expect(
    page.getByText(fmt(fixture.quicken.expectedAmped), { exact: true }).first()
  ).toBeVisible({ timeout: 5_000 });

  await page.getByTestId("reaction-select").selectOption("");
  await expect(
    page.getByText(fmt(fixture.quicken.expectedBase), { exact: true }).first()
  ).toBeVisible({ timeout: 5_000 });
});
